from __future__ import annotations

from datetime import date, datetime
from decimal import Decimal
from typing import Protocol

from pydantic import Field

from catalyst_router.domain import DecisionRecord, FrozenModel

UNIVERSE_POLICY_VERSION = "universe-v1"


class UniverseUnavailable(RuntimeError):
    pass


class UniverseCandidate(FrozenModel):
    symbol: str
    most_active_rank: int | None = Field(default=None, gt=0)
    gainer_rank: int | None = Field(default=None, gt=0)
    loser_rank: int | None = Field(default=None, gt=0)
    price: Decimal = Field(gt=0)
    prior_day_dollar_volume: Decimal = Field(ge=0)
    spread_bps: Decimal = Field(ge=0)
    active: bool
    tradable: bool
    options_enabled: bool


class UniverseSnapshot(FrozenModel):
    universe_id: str
    policy_version: str
    session_date: date
    selected_at: datetime
    symbols: tuple[str, ...]
    source_ranks: dict[str, dict[str, int]]
    rejections: dict[str, tuple[str, ...]]
    candidate_evidence: dict[str, UniverseCandidate] = Field(default_factory=dict)


class UniverseSelector:
    MIN_PRICE = Decimal("5")
    MIN_DOLLAR_VOLUME = Decimal("50000000")
    MAX_SPREAD_BPS = Decimal("15")

    def __init__(self, *, target_size: int = 20) -> None:
        if target_size < 1:
            raise ValueError("universe target size must be positive")
        self._target_size = target_size

    def select(
        self,
        *,
        session_date: date,
        selected_at: datetime,
        candidates: tuple[UniverseCandidate, ...],
    ) -> UniverseSnapshot:
        if selected_at.tzinfo is None:
            raise ValueError("universe selection time must be timezone-aware")
        merged = self._merge(candidates)
        accepted: list[tuple[float, str, UniverseCandidate]] = []
        rejections: dict[str, tuple[str, ...]] = {}
        source_ranks: dict[str, dict[str, int]] = {}
        for symbol, item in sorted(merged.items()):
            reasons = self._rejection_reasons(item)
            if reasons:
                rejections[symbol] = reasons
                continue
            ranks = {
                source: rank
                for source, rank in (
                    ("most_active", item.most_active_rank),
                    ("gainer", item.gainer_rank),
                    ("loser", item.loser_rank),
                )
                if rank is not None
            }
            source_ranks[symbol] = ranks
            score = sum(1 / (60 + rank) for rank in ranks.values())
            accepted.append((score, symbol, item))
        accepted.sort(key=lambda value: (-value[0], value[1]))
        symbols = tuple(symbol for _, symbol, _ in accepted[: self._target_size])
        selected_ranks = {symbol: source_ranks[symbol] for symbol in symbols}
        return UniverseSnapshot(
            universe_id=f"{UNIVERSE_POLICY_VERSION}:{session_date.isoformat()}",
            REDACTED,
            session_date=session_date,
            selected_at=selected_at,
            symbols=symbols,
            source_ranks=selected_ranks,
            rejections=rejections,
            candidate_evidence=merged,
        )

    @staticmethod
    def _merge(candidates: tuple[UniverseCandidate, ...]) -> dict[str, UniverseCandidate]:
        merged: dict[str, UniverseCandidate] = {}
        for item in candidates:
            symbol = item.symbol.upper()
            current = merged.get(symbol)
            if current is None:
                merged[symbol] = item.model_copy(update={"symbol": symbol})
                continue
            merged[symbol] = current.model_copy(
                update={
                    "most_active_rank": _minimum_rank(
                        current.most_active_rank, item.most_active_rank
                    ),
                    "gainer_rank": _minimum_rank(current.gainer_rank, item.gainer_rank),
                    "loser_rank": _minimum_rank(current.loser_rank, item.loser_rank),
                }
            )
        return merged

    def _rejection_reasons(self, item: UniverseCandidate) -> tuple[str, ...]:
        reasons = []
        if not item.active:
            reasons.append("asset is not active")
        if not item.tradable:
            reasons.append("asset is not tradable")
        if not item.options_enabled:
            reasons.append("options are not enabled")
        if item.price < self.MIN_PRICE:
            reasons.append("price below $5")
        if item.prior_day_dollar_volume < self.MIN_DOLLAR_VOLUME:
            reasons.append("prior-day dollar volume below $50M")
        if item.spread_bps > self.MAX_SPREAD_BPS:
            reasons.append("underlying spread exceeds 15 bps")
        return tuple(reasons)


class UniverseSource(Protocol):
    def session_date(self) -> date: ...

    def build(self, session_date: date) -> UniverseSnapshot: ...


class UniverseStore(Protocol):
    def get_daily_universe(self, session_date: date) -> UniverseSnapshot | None: ...

    def put_daily_universe(self, snapshot: UniverseSnapshot, *, expected_epoch: str) -> bool: ...

    def append_decision_once(
        self, record: DecisionRecord, *, expected_epoch: str | None = None
    ) -> bool: ...


class DailyUniverse:
    """Returns one immutable point-in-time universe for each Alpaca session."""

    def __init__(self, *, store: UniverseStore, source: UniverseSource) -> None:
        self._store = store
        self._source = source

    def current(self, *, expected_epoch: str) -> UniverseSnapshot:
        session_date = self._source.session_date()
        existing = self._store.get_daily_universe(session_date)
        if existing is not None:
            return existing
        proposed = self._source.build(session_date)
        if self._store.put_daily_universe(proposed, expected_epoch=expected_epoch):
            self._store.append_decision_once(
                DecisionRecord.create(
                    decision_id=proposed.universe_id,
                    decision_type="UNIVERSE_SELECTED",
                    occurred_at=proposed.selected_at,
                    summary=(
                        f"selected {len(proposed.symbols)} option-enabled underlyings "
                        f"for {proposed.session_date}"
                    ),
                    payload=proposed.model_dump(mode="json"),
                    public=True,
                    public_summary=f"Selected {len(proposed.symbols)} liquid underlyings",
                ),
                expected_epoch=expected_epoch,
            )
            return proposed
        winner = self._store.get_daily_universe(proposed.session_date)
        if winner is None:
            raise RuntimeError("daily universe was claimed but could not be loaded")
        return winner


def _minimum_rank(left: int | None, right: int | None) -> int | None:
    if left is None:
        return right
    if right is None:
        return left
    return min(left, right)

from __future__ import annotations

import logging
import time
from collections.abc import Callable
from datetime import UTC, datetime
from pathlib import Path
from typing import Protocol
from uuid import NAMESPACE_URL, uuid5

from catalyst_router.challenger import PublicChallengerStatus, ShadowPrediction
from catalyst_router.domain import DecisionRecord
from catalyst_router.ports import OperationalStore
from catalyst_router.training import FeatureVector, MarketBar, build_feature_vectors
from catalyst_router.universe import DailyUniverse, UniverseSnapshot, UniverseUnavailable

logger = logging.getLogger(__name__)


class MarketData(Protocol):
    def recent_bars(
        self,
        symbols: tuple[str, ...],
        *,
        timeframe_minutes: int,
        lookback_days: int,
    ) -> list[MarketBar]: ...


class ChallengerPredictor(Protocol):
    status: PublicChallengerStatus
    symbols: tuple[str, ...]

    def predict(self, vector: FeatureVector) -> ShadowPrediction: ...


class FeatureBuilder(Protocol):
    def build(self, bars: list[MarketBar]) -> tuple[FeatureVector, ...]: ...


class LiveTrader(Protocol):
    def manage(self, *, expected_epoch: str) -> tuple[DecisionRecord, ...]: ...

    def run(
        self,
        vectors: tuple[FeatureVector, ...],
        *,
        expected_epoch: str,
        universe_id: str | None = None,
    ) -> tuple[DecisionRecord, ...]: ...


class EventRouter(Protocol):
    def run(
        self, vectors: tuple[FeatureVector, ...], *, expected_epoch: str
    ) -> tuple[DecisionRecord, ...]: ...


class LiveFeatureBuilder:
    def __init__(self, feature_schema: str) -> None:
        self._feature_schema = feature_schema

    def build(self, bars: list[MarketBar]) -> tuple[FeatureVector, ...]:
        return build_feature_vectors(bars, feature_schema=self._feature_schema)


class TradingWorker:
    """Runs the always-on inference cycle; execution remains separately gated."""

    def __init__(
        self,
        *,
        store: OperationalStore,
        market_data: MarketData,
        challenger: ChallengerPredictor,
        universe: DailyUniverse,
        feature_builder: FeatureBuilder | None = None,
        live_trader: LiveTrader | None = None,
        event_router: EventRouter | None = None,
        live_started_at: datetime | None = None,
    ) -> None:
        self._store = store
        self._market_data = market_data
        self._challenger = challenger
        self._universe = universe
        self._feature_builder = feature_builder or LiveFeatureBuilder(
            challenger.status.feature_schema or "bar-features-v3"
        )
        self._live_trader = live_trader
        self._event_router = event_router
        self._live_started_at = (
            live_started_at or datetime.now(UTC) if live_trader is not None else None
        )
        self._execution_epoch: str | None = None
        self._bars: dict[tuple[str, datetime], MarketBar] = {}
        self._market_data_bootstrapped = False
        self._universe_id: str | None = None

    def run_cycle(self) -> tuple[DecisionRecord, ...]:
        state = self._store.get_agent_state()
        if not state.is_reconciled:
            raise RuntimeError("worker execution epoch is not reconciled")
        if self._execution_epoch is not None and state.execution_epoch != self._execution_epoch:
            raise RuntimeError("worker lost execution epoch ownership")
        if not self._challenger.status.deployed or not self._challenger.status.loaded:
            raise RuntimeError("challenger is not ready for inference")
        expected_epoch = self._execution_epoch or state.execution_epoch
        if self._live_trader is not None:
            management_records = self._live_trader.manage(expected_epoch=expected_epoch)
            if management_records:
                return management_records
        try:
            universe = self._universe.current(expected_epoch=expected_epoch)
        except UniverseUnavailable:
            return ()
        if universe.universe_id != self._universe_id:
            self._bars.clear()
            self._market_data_bootstrapped = False
            self._universe_id = universe.universe_id
        symbols = tuple(dict.fromkeys(("SPY", *universe.symbols)))
        timeframe = self._challenger.status.timeframe_minutes or 5
        bars = self._market_data.recent_bars(
            symbols,
            timeframe_minutes=timeframe,
            lookback_days=10 if not self._market_data_bootstrapped else 1,
        )
        self._market_data_bootstrapped = True
        self._bars.update({(bar.symbol, bar.timestamp): bar for bar in bars})
        vectors = self._feature_builder.build(list(self._bars.values()))
        if not vectors:
            return ()
        latest_by_symbol: dict[str, datetime] = {}
        for vector in vectors:
            latest_by_symbol[vector.symbol] = max(
                vector.observed_at,
                latest_by_symbol.get(vector.symbol, vector.observed_at),
            )
        latest_vectors = tuple(
            vector for vector in vectors if vector.observed_at == latest_by_symbol[vector.symbol]
        )
        records = []
        for vector in latest_vectors:
            prediction = self._challenger.predict(vector)
            record = self._prediction_record(prediction, universe)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch):
                records.append(record)
        if self._event_router is not None:
            try:
                records.extend(
                    self._event_router.run(latest_vectors, expected_epoch=expected_epoch)
                )
            except Exception:
                logger.exception("shadow event routing failed; live trading remains enabled")
        if self._live_trader is not None:
            eligible_vectors = tuple(
                vector
                for vector in latest_vectors
                if vector.symbol in universe.symbols
                and (self._live_started_at is None or vector.observed_at > self._live_started_at)
            )
            live_vectors = tuple(
                vector
                for vector in eligible_vectors
                if self._store.append_decision_once(
                    self._live_claim_record(vector), expected_epoch=expected_epoch
                )
            )
            if not live_vectors:
                return tuple(records)
            records.extend(
                self._live_trader.run(
                    live_vectors,
                    expected_epoch=expected_epoch,
                    universe_id=universe.universe_id,
                )
            )
        return tuple(records)

    def run_forever(
        self,
        *,
        reconcile: Callable[[], object],
        poll_seconds: int = 15,
        sleep: Callable[[float], None] = time.sleep,
        heartbeat_path: Path = Path("/tmp/worker-heartbeat"),
    ) -> None:
        reconcile()
        state = self._store.get_agent_state()
        if not state.is_reconciled:
            raise RuntimeError("startup reconciliation did not complete")
        self._execution_epoch = state.execution_epoch
        consecutive_failures = 0
        while True:
            try:
                records = self.run_cycle()
                consecutive_failures = 0
                if records:
                    logger.info("persisted %d worker decisions", len(records))
                heartbeat_path.touch()
            except Exception:
                consecutive_failures += 1
                logger.exception("trading worker cycle failed")
                if consecutive_failures >= 5:
                    raise
            sleep(poll_seconds)

    def _prediction_record(
        self, prediction: ShadowPrediction, universe: UniverseSnapshot
    ) -> DecisionRecord:
        authority = self._challenger.status.authority or "SHADOW_ONLY"
        model_label = "paper-live model" if authority == "PAPER_LIVE" else "shadow model"
        decision_id = str(
            uuid5(
                NAMESPACE_URL,
                ":".join(
                    (
                        "challenger-prediction",
                        prediction.run_id,
                        prediction.symbol,
                        prediction.observed_at.isoformat(),
                    )
                ),
            )
        )
        return DecisionRecord.create(
            decision_id=decision_id,
            decision_type="CHALLENGER_PREDICTION",
            occurred_at=prediction.observed_at,
            symbol=prediction.symbol,
            summary=(
                f"{model_label} {prediction.run_id} predicted {prediction.value:.6f} "
                f"({prediction.signal})"
            ),
            payload={
                "authority": authority,
                "run_id": prediction.run_id,
                "value": prediction.value,
                "signal": prediction.signal,
                "universe_id": universe.universe_id,
            },
            public=True,
            public_summary=f"{model_label.title()} signal: {prediction.signal}",
        )

    def _live_claim_record(self, vector: FeatureVector) -> DecisionRecord:
        run_id = self._challenger.status.run_id or "unknown-model"
        return DecisionRecord.create(
            decision_id=str(
                uuid5(
                    NAMESPACE_URL,
                    ":".join(
                        (
                            "live-bar-evaluation",
                            run_id,
                            vector.symbol,
                            vector.observed_at.isoformat(),
                        )
                    ),
                )
            ),
            decision_type="LIVE_BAR_EVALUATION_CLAIM",
            occurred_at=vector.observed_at,
            symbol=vector.symbol,
            summary=f"claimed one live evaluation for {run_id}",
        )

from __future__ import annotations

from decimal import Decimal
from typing import cast

from alpaca.common.exceptions import APIError
from alpaca.trading.client import TradingClient
from alpaca.trading.enums import (
    OrderClass,
    OrderSide,
    PositionIntent,
    QueryOrderStatus,
    TimeInForce,
)
from alpaca.trading.models import Clock, Order, Position, TradeAccount
from alpaca.trading.requests import (
    GetOrdersRequest,
    LimitOrderRequest,
    MarketOrderRequest,
    StopLossRequest,
    TakeProfitRequest,
)

from catalyst_router.domain import (
    AccountSnapshot,
    BrokerOrderSnapshot,
    InstrumentType,
    MarketClockSnapshot,
    OpenOrderSnapshot,
    OrderPlan,
    PositionSnapshot,
    ReconciliationSnapshot,
    Side,
)

ALPACA_PAPER_BASE_URL = "https://paper-api.alpaca.markets"
ALPACA_PAPER_API_ROOT = f"{ALPACA_PAPER_BASE_URL}/v2"
# Alpaca reports a filled bracket's exits as an OCO pair: the working leg is
# "new" while its resting sibling is "held". A held leg is live server-side
# protection, so excluding it would read every protected position as unprotected.
_ACTIVE_PROTECTIVE_STATUSES = {
    "accepted",
    "held",
    "new",
    "partially_filled",
    "pending_new",
}


class AlpacaPaperBroker:
    """Alpaca adapter hard-pinned to the paper-trading endpoint."""

    def __init__(self, key: str, secret: str) -> None:
        self._client = TradingClient(
            key,
            secret,
            paper=True,
            url_override=ALPACA_PAPER_BASE_URL,
        )

    def reconciliation_snapshot(self) -> ReconciliationSnapshot:
        account = cast(TradeAccount, self._client.get_account())
        clock = cast(Clock, self._client.get_clock())
        positions = cast(list[Position], self._client.get_all_positions())
        orders = cast(
            list[Order],
            self._client.get_orders(
                filter=GetOrdersRequest(status=QueryOrderStatus.OPEN, limit=500)
            ),
        )
        return ReconciliationSnapshot(
            account=AccountSnapshot(
                equity=Decimal(str(account.equity)),
                buying_power=Decimal(str(account.buying_power)),
                cash=Decimal(str(account.cash)),
                portfolio_value=Decimal(str(account.portfolio_value)),
                trading_blocked=bool(account.trading_blocked),
                options_trading_level=int(account.options_trading_level or 0),
                options_buying_power=(
                    Decimal(str(account.options_buying_power))
                    if account.options_buying_power is not None
                    else None
                ),
                last_equity=(
                    Decimal(str(account.last_equity)) if account.last_equity is not None else None
                ),
            ),
            clock=MarketClockSnapshot(
                is_open=bool(clock.is_open),
                timestamp=clock.timestamp,
                next_open=clock.next_open,
                next_close=clock.next_close,
            ),
            positions=tuple(
                PositionSnapshot(
                    symbol=position.symbol,
                    asset_class=str(position.asset_class),
                    quantity=Decimal(str(position.qty)),
                    market_value=Decimal(str(position.market_value or 0)),
                    unrealized_pl=Decimal(str(position.unrealized_pl or 0)),
                )
                for position in positions
            ),
            open_orders=tuple(
                OpenOrderSnapshot(
                    client_order_id=order.client_order_id,
                    symbol=order.symbol or "",
                    status=str(order.status),
                    side=str(order.side or ""),
                    quantity=Decimal(str(order.qty)) if order.qty is not None else None,
                )
                for order in orders
            ),
        )

    def get_order_by_client_id(self, client_order_id: str) -> BrokerOrderSnapshot | None:
        try:
            order = cast(Order, self._client.get_order_by_client_id(client_order_id))
        except APIError as exc:
            if exc.status_code == 404:
                return None
            raise
        return self._order_snapshot(order)

    def submit_order(self, plan: OrderPlan) -> BrokerOrderSnapshot:
        if plan.instrument_type is InstrumentType.OPTION:
            if plan.side is not Side.BUY:
                raise ValueError("option opening orders must buy to open")
            request = LimitOrderRequest(
                symbol=plan.symbol,
                qty=plan.quantity,
                side=OrderSide.BUY,
                time_in_force=TimeInForce.DAY,
                extended_hours=False,
                client_order_id=plan.client_order_id,
                limit_price=float(plan.limit_price),
                position_intent=PositionIntent.BUY_TO_OPEN,
            )
        else:
            request = LimitOrderRequest(
                symbol=plan.symbol,
                qty=plan.quantity,
                side=OrderSide.BUY if plan.side is Side.BUY else OrderSide.SELL,
                time_in_force=TimeInForce.DAY,
                order_class=OrderClass.BRACKET,
                extended_hours=False,
                client_order_id=plan.client_order_id,
                limit_price=float(plan.limit_price),
                take_profit=TakeProfitRequest(limit_price=float(plan.take_profit_price)),
                stop_loss=StopLossRequest(stop_price=float(plan.stop_price)),
            )
        order = cast(
            Order,
            self._client.submit_order(request),
        )
        return self._order_snapshot(order)

    def close_position(self, symbol: str) -> None:
        """Cancels the symbol's resting bracket legs, then closes just that position."""
        orders = cast(
            list[Order],
            self._client.get_orders(
                filter=GetOrdersRequest(status=QueryOrderStatus.OPEN, symbols=[symbol], limit=500)
            ),
        )
        for order in orders:
            try:
                self._client.cancel_order_by_id(str(order.id))
            except APIError as exc:
                if exc.status_code not in {404, 422}:
                    raise
        try:
            self._client.close_position(symbol)
        except APIError as exc:
            if exc.status_code != 404:
                raise

    def submit_option_exit(
        self, symbol: str, quantity: int, client_order_id: str
    ) -> BrokerOrderSnapshot:
        order = cast(
            Order,
            self._client.submit_order(
                MarketOrderRequest(
                    symbol=symbol,
                    qty=quantity,
                    side=OrderSide.SELL,
                    time_in_force=TimeInForce.DAY,
                    extended_hours=False,
                    client_order_id=client_order_id,
                    position_intent=PositionIntent.SELL_TO_CLOSE,
                )
            ),
        )
        return self._order_snapshot(order)

    def flatten(self) -> None:
        self._client.close_all_positions(cancel_orders=True)

    @staticmethod
    def _order_snapshot(order: Order) -> BrokerOrderSnapshot:
        if order.symbol is None or order.side is None or order.qty is None:
            raise RuntimeError("Alpaca order response is incomplete")
        active_legs = [
            leg
            for leg in getattr(order, "legs", None) or []
            if str(leg.status).rsplit(".", 1)[-1].lower() in _ACTIVE_PROTECTIVE_STATUSES
        ]
        return BrokerOrderSnapshot(
            order_id=str(order.id),
            client_order_id=order.client_order_id,
            symbol=order.symbol,
            side=Side.BUY if order.side == OrderSide.BUY else Side.SELL,
            quantity=int(Decimal(str(order.qty))),
            status=str(order.status),
            has_active_take_profit=any(
                str(leg.type).rsplit(".", 1)[-1].lower() == "limit" for leg in active_legs
            ),
            has_active_stop_loss=any(
                str(leg.type).rsplit(".", 1)[-1].lower() in {"stop", "stop_limit"}
                for leg in active_legs
            ),
        )

from __future__ import annotations

import base64
import hashlib
import json
from binascii import Error as BinasciiError
from datetime import UTC, date, datetime, timedelta
from decimal import Decimal
from typing import TYPE_CHECKING, Any, cast
from uuid import uuid4

import boto3
from boto3.dynamodb.conditions import Key
from boto3.dynamodb.types import TypeSerializer
from botocore.exceptions import ClientError

from catalyst_router.domain import (
    AgentMode,
    AgentState,
    DecisionRecord,
    OrderExecution,
    OrderExecutionStatus,
    PublicDecisionPage,
    PublicDecisionRecord,
    PublicPortfolioPoint,
