                intent,
                agent,
                portfolio,
                market_is_open=snapshot.clock.is_open,
                trading_blocked=snapshot.account.trading_blocked,
                options_trading_level=snapshot.account.options_trading_level,
                options_buying_power=(
                    min(
                        snapshot.account.options_buying_power,
                        snapshot.account.equity * self.MAX_ENTRY_NOTIONAL_RATE,
                    )
                    if snapshot.account.options_buying_power is not None
                    else None
                ),
            )
            if risk.status is RiskDecisionStatus.VETOED:
                return self._persist_risk_veto(intent, risk, expected_epoch)
            approvals = self._persist_risk_approval(intent, risk, portfolio, expected_epoch)
            execution = self._gateway.execute(
                intent,
                risk,
                expected_epoch=expected_epoch,
                max_active_orders=self.MAX_CONCURRENT_POSITIONS,
            )
            return approvals + self._persist_execution(intent, risk, execution, expected_epoch)
        return ()

    def manage(self, *, expected_epoch: str) -> tuple[DecisionRecord, ...]:
        return self.run((), expected_epoch=expected_epoch)

    @staticmethod
    def _group_open_risk(tracked: dict[str, OrderExecution]) -> dict[str, Decimal]:
        group_open_risk: dict[str, Decimal] = {}
        for execution in tracked.values():
            plan = execution.plan
            group_open_risk[plan.exposure_group] = (
                group_open_risk.get(plan.exposure_group, Decimal("0")) + plan.risk_amount
            )
        return group_open_risk

    def _every_position_is_protected(
        self, snapshot: ReconciliationSnapshot, tracked: dict[str, OrderExecution]
    ) -> bool:
        protected: set[str] = set()
        positions = {position.symbol: position for position in snapshot.positions}
        for client_order_id, execution in tracked.items():
            if execution.plan.instrument_type is InstrumentType.OPTION:
                position = positions.get(execution.plan.symbol)
                expiration = execution.plan.option_expiration_date
                if (
                    position is not None
                    and position.quantity > 0
                    and expiration is not None
                    and expiration > snapshot.clock.timestamp.date()
                ):
                    protected.add(execution.plan.symbol)
                continue
            broker_order = self._broker.get_order_by_client_id(client_order_id)
            if (
                broker_order is not None
                and broker_order.has_active_take_profit
                and broker_order.has_active_stop_loss
            ):
                protected.add(execution.plan.symbol)
        return all(position.symbol in protected for position in snapshot.positions)

    def _manage_option_exits(
        self,
        snapshot: ReconciliationSnapshot,
        tracked: dict[str, OrderExecution],
        expected_epoch: str,
    ) -> tuple[DecisionRecord, ...]:
        positions = {position.symbol: position for position in snapshot.positions}
        for client_order_id, execution in tracked.items():
            plan = execution.plan
            position = positions.get(plan.symbol)
            if plan.instrument_type is not InstrumentType.OPTION or position is None:
                continue
            if self._option_quotes is None:
                raise RuntimeError("option position supervision is not configured")
            reason = None
            quote: QuoteSnapshot | None = None
            if snapshot.clock.timestamp >= plan.expires_at:
                reason = "model horizon elapsed"
            else:
                try:
                    quote = self._option_quotes.latest_quote(plan.symbol)
                except Exception:
                    continue
                quote_age = snapshot.clock.timestamp - quote.timestamp
                if quote.feed != "indicative" or not (
                    -ModelStrategy.MAX_CLOCK_SKEW <= quote_age <= timedelta(seconds=5)
                ):
                    continue
                if quote.bid_price <= plan.stop_price:
                    reason = "premium stop reached"
                elif quote.bid_price >= plan.take_profit_price:
                    reason = "premium target reached"
            if reason is None:
                continue
            exit_client_order_id = (
                "crx-" + uuid5(NAMESPACE_URL, f"option-exit-v1:{plan.client_order_id}").hex
            )
            broker_exit = self._broker.get_order_by_client_id(exit_client_order_id)
            if broker_exit is not None and self._is_terminal_rejection(broker_exit.status):
                self._halt_and_flatten(
                    AgentMode.RISK_HALTED,
                    f"option exit {exit_client_order_id} was rejected or canceled",
                )
                return ()
            if broker_exit is None:
                try:
                    broker_exit = self._broker.submit_option_exit(
                        plan.symbol,
                        int(position.quantity),
                        exit_client_order_id,
                    )
                except Exception:
                    self._halt_and_flatten(
                        AgentMode.RISK_HALTED,
                        f"option exit {exit_client_order_id} submission failed",
                    )
                    return ()
                if self._is_terminal_rejection(broker_exit.status):
                    self._halt_and_flatten(
                        AgentMode.RISK_HALTED,
                        f"option exit {exit_client_order_id} was rejected",
                    )
                    return ()
            record = DecisionRecord.create(
                decision_id=str(uuid5(NAMESPACE_URL, f"option-exit:{client_order_id}:{reason}")),
                decision_type="OPTION_EXIT",
                route=Route.MODEL_DIRECTIONAL,
                symbol=plan.underlying_symbol or plan.symbol,
                summary=f"closed {plan.symbol}: {reason}",
                payload={
                    "contract_symbol": plan.symbol,
                    "reason": reason,
                    "bid_price": str(quote.bid_price) if quote is not None else None,
                    "exit_client_order_id": exit_client_order_id,
                    "broker_status": broker_exit.status,
                    "universe_id": plan.universe_id,
                },
                public=True,
                public_summary=f"Closed option position: {reason}",
            )
            return (
                (record,)
                if self._store.append_decision_once(record, expected_epoch=expected_epoch)
                else ()
            )
        return ()

    @staticmethod
    def _is_terminal_rejection(status: str) -> bool:
        return status.rsplit(".", 1)[-1].lower() in {
            "canceled",
            "expired",
            "rejected",
            "replaced",
        }

    def _release_terminal_orders(
        self, agent: AgentState, snapshot: ReconciliationSnapshot
    ) -> tuple[AgentState, dict[str, OrderExecution]]:
        tracked: dict[str, OrderExecution] = {}
        released = False
        for client_order_id in agent.active_order_ids:
            execution = self._store.get_order(client_order_id)
            if execution is None:
                raise RuntimeError("active order has no durable execution record")
            if self._release_terminal_order(client_order_id, snapshot, execution):
                released = True
                continue
            tracked[client_order_id] = execution
        return (self._store.get_agent_state() if released else agent), tracked

    def _release_terminal_order(
        self,
        client_order_id: str,
        snapshot: ReconciliationSnapshot,
        execution: OrderExecution,
    ) -> bool:
        broker_order = self._broker.get_order_by_client_id(client_order_id)
        status = (
            broker_order.status.rsplit(".", 1)[-1].lower()
            if broker_order is not None
            else "missing"
        )
        terminal = status in {"canceled", "expired", "filled", "rejected", "replaced"}
        expired_and_missing = (
            status == "missing" and snapshot.clock.timestamp >= execution.plan.expires_at
        )
        symbol = execution.plan.symbol
        symbol_is_flat = not any(
            position.symbol == symbol for position in snapshot.positions
        ) and not any(order.symbol == symbol for order in snapshot.open_orders)
        if (terminal or expired_and_missing) and symbol_is_flat:
            self._store.clear_active_order(client_order_id)
            return True
        return False

    def _halt_and_flatten(self, mode: AgentMode, reason: str) -> None:
        self._store.transition_agent_mode(
            mode,
            reason=reason,
            record=DecisionRecord.create(
                decision_type="CIRCUIT_BREAKER",
                summary=reason,
                payload={"mode": mode, "reason": reason},
            ),
        )
        self._broker.flatten()

    def _persist_risk_veto(
        self, intent: TradeIntent, risk: RiskDecision, expected_epoch: str
    ) -> tuple[DecisionRecord, ...]:
        record = DecisionRecord.create(
            decision_id=str(uuid5(NAMESPACE_URL, f"risk-veto:{intent.intent_id}")),
            decision_type="RISK_VETO",
            route=intent.route,
            symbol=intent.underlying_symbol or intent.symbol,
            summary="; ".join(risk.checks),
            payload={
                "intent_id": intent.intent_id,
                "contract_symbol": intent.symbol,
                "universe_id": intent.universe_id,
                "checks": risk.checks,
            },
            public=True,
            public_summary=f"Risk governor vetoed {intent.symbol}",
        )
        return (
            (record,)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch)
            else ()
        )

    def _persist_risk_approval(
        self,
        intent: TradeIntent,
        risk: RiskDecision,
        portfolio: PortfolioRiskState,
        expected_epoch: str,
    ) -> tuple[DecisionRecord, ...]:
        record = DecisionRecord.create(
            decision_id=str(uuid5(NAMESPACE_URL, f"risk-approval:{intent.intent_id}")),
            decision_type="RISK_APPROVAL",
            route=intent.route,
            symbol=intent.underlying_symbol or intent.symbol,
            summary=f"approved {risk.quantity} units with {risk.risk_amount} maximum risk",
            payload={
                "intent_id": intent.intent_id,
                "status": risk.status,
                "quantity": risk.quantity,
                "risk_amount": str(risk.risk_amount),
                "checks": risk.checks,
                "contract_symbol": intent.symbol,
                "universe_id": intent.universe_id,
                "account_snapshot": {
                    "equity": str(portfolio.equity),
                    "buying_power": str(portfolio.buying_power),
                    "position_count": portfolio.position_count,
                    "total_open_risk": str(portfolio.total_open_risk),
                    "daily_pnl": str(portfolio.daily_pnl),
                    "competition_drawdown": str(portfolio.competition_drawdown),
                },
            },
        )
        return (
            (record,)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch)
            else ()
        )

    def _persist_execution(
        self,
        intent: TradeIntent,
        risk: RiskDecision,
        execution: OrderExecution,
        expected_epoch: str,
    ) -> tuple[DecisionRecord, ...]:
        record = DecisionRecord.create(
            decision_id=str(
                uuid5(NAMESPACE_URL, f"order-execution:{execution.plan.client_order_id}")
            ),
            decision_type="ORDER_EXECUTION",
            route=intent.route,
            symbol=intent.underlying_symbol or intent.symbol,
            summary=(
                f"{execution.status} paper order {execution.plan.client_order_id} "
                f"for {execution.plan.quantity} {intent.symbol}"
            ),
            payload={
                "client_order_id": execution.plan.client_order_id,
                "status": execution.status,
                "quantity": execution.plan.quantity,
                "risk_amount": str(risk.risk_amount),
                "limit_price": str(execution.plan.limit_price),
                "stop_price": str(execution.plan.stop_price),
                "take_profit_price": str(execution.plan.take_profit_price),
                "contract_symbol": intent.symbol,
                "universe_id": intent.universe_id,
            },
            public=True,
            public_summary=f"Paper order {execution.status.lower()} for {intent.symbol}",
        )
        return (
            (record,)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch)
            else ()
        )


class ExecutionGateway:
    def __init__(self, *, store: OperationalStore, broker: PaperBroker) -> None:
        self._store = store
        self._broker = broker

    def execute(
        self,
        intent: TradeIntent,
        risk: RiskDecision,
        *,
        expected_epoch: str,
        max_active_orders: int,
    ) -> OrderExecution:
        if risk.intent_id != intent.intent_id or risk.status is RiskDecisionStatus.VETOED:
            raise ValueError("an approved risk decision matching the intent is required")
        plan = self._plan(intent, risk)
        prepared = OrderExecution(plan=plan, request_hash=self._request_hash(plan))
        claimed = self._store.claim_order(
            prepared, expected_epoch=expected_epoch, max_active_orders=max_active_orders
        )
        execution = prepared if claimed else self._store.get_order(plan.client_order_id)
        if execution is None:
            raise RuntimeError("claimed order execution could not be loaded")
        if execution.request_hash != prepared.request_hash:
            raise RuntimeError("client order id was reused with a different request")
        if execution.status in {
            OrderExecutionStatus.ACKNOWLEDGED,
            OrderExecutionStatus.REJECTED,
        }:
            return execution

        broker_order = self._broker.get_order_by_client_id(plan.client_order_id)
        if broker_order is not None:
            return self._acknowledge(execution, broker_order)
        try:
            broker_order = self._broker.submit_order(plan)
        except Exception:
            broker_order = self._broker.get_order_by_client_id(plan.client_order_id)
            if broker_order is not None:
                return self._acknowledge(execution, broker_order)
            return self._transition(execution, OrderExecutionStatus.UNKNOWN)
        return self._acknowledge(execution, broker_order)

    @staticmethod
    def _plan(intent: TradeIntent, risk: RiskDecision) -> OrderPlan:
        client_order_id = "cr-" + uuid5(NAMESPACE_URL, f"paper-order-v1:{intent.intent_id}").hex
        take_profit = intent.take_profit_price or (
            (intent.entry_price * Decimal("1.04")).quantize(_CENT, rounding=ROUND_CEILING)
            if intent.side is Side.BUY
            else (intent.entry_price * Decimal("0.96")).quantize(_CENT, rounding=ROUND_FLOOR)
        )
        created_at = datetime.now(UTC)
        return OrderPlan(
            client_order_id=client_order_id,
            intent_id=intent.intent_id,
            symbol=intent.symbol,
            side=intent.side,
            quantity=risk.quantity,
            limit_price=intent.entry_price,
            stop_price=intent.stop_price,
            take_profit_price=take_profit,
            risk_amount=risk.risk_amount,
            exposure_group=intent.exposure_group,
            instrument_type=intent.instrument_type,
            underlying_symbol=intent.underlying_symbol,
            option_type=intent.option_type,
            option_expiration_date=intent.option_expiration_date,
            universe_id=intent.universe_id,
            created_at=created_at,
            expires_at=created_at + timedelta(minutes=intent.expected_horizon_minutes),
        )

    @staticmethod
    def _request_hash(plan: OrderPlan) -> str:
        if plan.instrument_type is InstrumentType.OPTION:
            request = {
                "client_order_id": plan.client_order_id,
                "limit_price": str(plan.limit_price),
                "position_intent": "buy_to_open",
                "quantity": plan.quantity,
                "side": plan.side,
                "symbol": plan.symbol,
                "time_in_force": "day",
                "type": "limit",
            }
        else:
            request = {
                "client_order_id": plan.client_order_id,
                "limit_price": str(plan.limit_price),
                "quantity": plan.quantity,
                "side": plan.side,
                "stop_price": str(plan.stop_price),
                "symbol": plan.symbol,
                "take_profit_price": str(plan.take_profit_price),
                "time_in_force": "day",
                "type": "limit",
            }
        encoded = json.dumps(request, sort_keys=True, separators=(",", ":")).encode()
        return hashlib.sha256(encoded).hexdigest()

    def _acknowledge(
        self, execution: OrderExecution, broker_order: BrokerOrderSnapshot
    ) -> OrderExecution:
        plan = execution.plan
        if (
            broker_order.client_order_id != plan.client_order_id
            or broker_order.symbol != plan.symbol
            or broker_order.side is not plan.side
            or broker_order.quantity != plan.quantity
        ):
            raise RuntimeError("Alpaca order does not match the durable order plan")
        status = broker_order.status.rsplit(".", 1)[-1].lower()
        target = (
            OrderExecutionStatus.REJECTED
            if status in {"canceled", "expired", "rejected", "replaced"}
            else OrderExecutionStatus.ACKNOWLEDGED
        )
        updated = self._transition(
            execution,
            target,
            alpaca_order_id=broker_order.order_id,
            broker_status=broker_order.status,
        )
        if target is OrderExecutionStatus.REJECTED:
            self._store.clear_active_order(plan.client_order_id)
        return updated

    def _transition(
        self,
        execution: OrderExecution,
        status: OrderExecutionStatus,
        *,
        alpaca_order_id: str | None = None,
        broker_status: str | None = None,
    ) -> OrderExecution:
        updated = execution.model_copy(
            update={
                "status": status,
                "version": execution.version + 1,
                "alpaca_order_id": alpaca_order_id or execution.alpaca_order_id,
                "broker_status": broker_status or execution.broker_status,
                "updated_at": datetime.now(UTC),
            }
        )
        return self._store.update_order(updated, expected_status=execution.status)

from decimal import ROUND_FLOOR, Decimal

from catalyst_router.domain import (
    AgentMode,
    AgentState,
    InstrumentType,
    PortfolioRiskState,
    RiskDecision,
    RiskDecisionStatus,
    Route,
    Side,
    TradeIntent,
)


class RiskGovernor:
    MAX_POSITIONS = 6
    MAX_TRADE_RISK_RATE = Decimal("0.01")
    REDUCED_TRADE_RISK_RATE = Decimal("0.005")
    MAX_TOTAL_RISK_RATE = Decimal("0.04")
    MAX_OVERNIGHT_RISK_RATE = Decimal("0.02")
    MAX_GROUP_RISK_RATE = Decimal("0.02")
    DE_RISK_DAILY_LOSS_RATE = Decimal("0.02")
    MAX_DAILY_LOSS_RATE = Decimal("0.04")
    MAX_COMPETITION_DRAWDOWN_RATE = Decimal("0.12")
    MAX_QUOTE_AGE_SECONDS = Decimal("5")

    def __init__(self, *, options_execution_enabled: bool = False) -> None:
        self._options_execution_enabled = options_execution_enabled

    def evaluate(
        self,
        intent: TradeIntent,
        agent: AgentState,
        portfolio: PortfolioRiskState,
        *,
        market_is_open: bool,
        overnight: bool = False,
        trading_blocked: bool = False,
        options_trading_level: int = 0,
        options_buying_power: Decimal | None = None,
    ) -> RiskDecision:
        vetoes: list[str] = []
        if intent.route is Route.NO_TRADE:
            vetoes.append("NO_TRADE cannot create exposure")
        if intent.instrument_type is InstrumentType.OPTION and intent.side is not Side.BUY:
            vetoes.append("short option legs are prohibited")
        if intent.instrument_type is InstrumentType.OPTION and not self._options_execution_enabled:
            vetoes.append("live option execution is not enabled")
        if intent.instrument_type is InstrumentType.OPTION and options_trading_level < 2:
            vetoes.append("options trading level 2 is required")
        if intent.route is Route.LIQUIDITY_REVERSION and (
            intent.instrument_type is not InstrumentType.EQUITY
        ):
            vetoes.append("liquidity reversion must use equities")
        if intent.route is Route.REGIME_TREND and (
            intent.instrument_type is not InstrumentType.EQUITY
        ):
            vetoes.append("regime trend must use equities")
        if trading_blocked:
            vetoes.append("Alpaca account is blocked from trading")
        if agent.mode is not AgentMode.RUNNING:
            vetoes.append(f"agent mode is {agent.mode}")
        if not agent.is_reconciled:
            vetoes.append("startup reconciliation is incomplete")
        if not market_is_open:
            vetoes.append("market is closed")
        if not intent.data_quality_passed:
            vetoes.append("intent data failed quality gates")
        if intent.quote_age_seconds > self.MAX_QUOTE_AGE_SECONDS:
            vetoes.append("quote is stale")
        if intent.stop_distance <= 0:
            vetoes.append("stop distance must be positive")
        if intent.side is Side.BUY and intent.stop_price >= intent.entry_price:
            vetoes.append("buy stop must be below entry")
        if intent.side is Side.SELL and intent.stop_price <= intent.entry_price:
            vetoes.append("sell stop must be above entry")
        if portfolio.position_count >= self.MAX_POSITIONS:
            vetoes.append("maximum position count reached")

        daily_loss = max(Decimal("0"), -portfolio.daily_pnl)
        if daily_loss >= portfolio.equity * self.MAX_DAILY_LOSS_RATE:
            vetoes.append("daily loss circuit breaker reached")
        if portfolio.competition_drawdown >= self.MAX_COMPETITION_DRAWDOWN_RATE:
            vetoes.append("competition drawdown kill threshold reached")

        if vetoes:
            return self._veto(intent, vetoes)

        risk_rate = (
            self.REDUCED_TRADE_RISK_RATE
            if daily_loss >= portfolio.equity * self.DE_RISK_DAILY_LOSS_RATE
            else self.MAX_TRADE_RISK_RATE
        )
        allowed_risk = portfolio.equity * risk_rate
        total_capacity = portfolio.equity * self.MAX_TOTAL_RISK_RATE - portfolio.total_open_risk
        group_capacity = (
            portfolio.equity * self.MAX_GROUP_RISK_RATE
            - portfolio.group_open_risk.get(intent.exposure_group, Decimal("0"))
        )
        capacities = [allowed_risk, total_capacity, group_capacity]
        if overnight:
            capacities.append(
                portfolio.equity * self.MAX_OVERNIGHT_RISK_RATE - portfolio.overnight_open_risk
            )
        risk_amount = max(Decimal("0"), min(capacities))
        buying_power = (
            options_buying_power
            if intent.instrument_type is InstrumentType.OPTION
            else portfolio.buying_power
        )
        if buying_power is None:
            return self._veto(intent, ["options buying power is unavailable"])
        affordable = (buying_power / intent.entry_cost_per_unit).to_integral_value(
            rounding=ROUND_FLOOR
        )
        by_stop = (risk_amount / intent.stop_risk_per_unit).to_integral_value(rounding=ROUND_FLOOR)
        quantity = int(min(affordable, by_stop))
        if quantity < 1:
            return self._veto(intent, ["risk or buying-power capacity is insufficient"])

        actual_risk = intent.stop_risk_per_unit * quantity
        status = (
            RiskDecisionStatus.REDUCED
            if risk_amount < allowed_risk or risk_rate < self.MAX_TRADE_RISK_RATE
            else RiskDecisionStatus.APPROVED
        )
        return RiskDecision(
            status=status,
            intent_id=intent.intent_id,
            quantity=quantity,
            risk_amount=actual_risk,
            checks=(
                "agent running and reconciled",
                "data and market gates passed",
                "trade, portfolio, group, and buying-power limits passed",
            ),
        )

    @staticmethod
    def _veto(intent: TradeIntent, vetoes: list[str]) -> RiskDecision:
        return RiskDecision(
            status=RiskDecisionStatus.VETOED,
            intent_id=intent.intent_id,
            quantity=0,
            risk_amount=Decimal("0"),
            checks=tuple(vetoes),
        )

from __future__ import annotations

from datetime import UTC, date, datetime, timedelta
from decimal import Decimal
from threading import RLock
from uuid import uuid4

from catalyst_router.domain import (
    AgentMode,
    AgentState,
    DecisionRecord,
    OrderExecution,
    OrderExecutionStatus,
    PublicDecisionPage,
    PublicDecisionRecord,
    PublicPortfolioPoint,
    Route,
)
from catalyst_router.universe import UniverseSnapshot


class InMemoryOperationalStore:
    def __init__(self, public_delay_seconds: int = 0) -> None:
        self._lock = RLock()
        self._state: AgentState | None = None
        self._decisions: dict[str, DecisionRecord] = {}
        self._orders: dict[str, OrderExecution] = {}
        self._public_portfolio: dict[datetime, PublicPortfolioPoint] = {}
        self._event_extractions: set[tuple[str, str, str]] = set()
        self._universes: dict[date, UniverseSnapshot] = {}
        self._public_delay = timedelta(seconds=public_delay_seconds)

    def initialize(self) -> AgentState:
        with self._lock:
            if self._state is None:
                self._state = AgentState()
            return self._state

    def get_agent_state(self) -> AgentState:
        with self._lock:
            return self.initialize()

    def begin_execution(self) -> AgentState:
        with self._lock:
            state = self.initialize()
            self._state = state.model_copy(
                update={
                    "version": state.version + 1,
                    "execution_epoch": str(uuid4()),
                    "reconciled_epoch": None,
                    "updated_at": datetime.now(UTC),
                }
            )
            return self._state

    def transition_agent_mode(
        self, mode: AgentMode, *, reason: str, record: DecisionRecord
    ) -> AgentState:
        with self._lock:
            state = self.initialize()
            if state.mode is AgentMode.KILLED:
                raise RuntimeError("KILLED agent mode is terminal")
            if mode is AgentMode.RUNNING and not state.is_reconciled:
                raise RuntimeError("startup reconciliation is required before RUNNING")
            if record.decision_id in self._decisions:
                raise ValueError(f"decision already exists: {record.decision_id}")
            self._state = state.model_copy(
                update={
                    "mode": mode,
                    "reason": reason,
                    "version": state.version + 1,
                    "updated_at": datetime.now(UTC),
                }
            )
            self._decisions[record.decision_id] = record
            return self._state

    def commit_reconciliation(
        self, epoch: str, record: DecisionRecord, *, equity: Decimal | None = None
    ) -> AgentState:
        with self._lock:
            state = self.initialize()
            if state.execution_epoch != epoch:
                raise RuntimeError("execution epoch changed during reconciliation")
            if record.decision_id in self._decisions:
                raise ValueError(f"decision already exists: {record.decision_id}")
            self._state = state.model_copy(
                update={
                    "version": state.version + 1,
                    "reconciled_epoch": epoch,
                    "equity_peak": (
                        max(state.equity_peak or equity, equity)
                        if equity is not None
                        else state.equity_peak
                    ),
                    "competition_start_equity": (
                        state.competition_start_equity or state.equity_peak or equity
                    ),
                    "updated_at": datetime.now(UTC),
                }
            )
            self._decisions[record.decision_id] = record
            return self._state

    def append_decision(self, record: DecisionRecord) -> None:
        with self._lock:
            if record.decision_id in self._decisions:
                raise ValueError(f"decision already exists: {record.decision_id}")
            self._decisions[record.decision_id] = record

    def append_decision_once(
        self, record: DecisionRecord, *, expected_epoch: str | None = None
    ) -> bool:
        with self._lock:
            state = self.initialize()
            if expected_epoch is not None and (
                state.execution_epoch != expected_epoch or not state.is_reconciled
            ):
                raise RuntimeError("worker lost execution epoch ownership")
            if record.decision_id in self._decisions:
                return False
            self._decisions[record.decision_id] = record
            return True

    def append_public_portfolio(self, point: PublicPortfolioPoint, *, expected_epoch: str) -> bool:
        with self._lock:
            state = self.initialize()
            if state.execution_epoch != expected_epoch or not state.is_reconciled:
                raise RuntimeError("worker lost execution epoch ownership")
            if point.captured_at in self._public_portfolio:
                return False
            self._public_portfolio[point.captured_at] = point
            return True

    def get_daily_universe(self, session_date: date) -> UniverseSnapshot | None:
        with self._lock:
            return self._universes.get(session_date)

    def put_daily_universe(self, snapshot: UniverseSnapshot, *, expected_epoch: str) -> bool:
        with self._lock:
            state = self.initialize()
            if state.execution_epoch != expected_epoch or not state.is_reconciled:
                raise RuntimeError("worker lost execution epoch ownership")
            if snapshot.session_date in self._universes:
                return False
            self._universes[snapshot.session_date] = snapshot
            return True

    def claim_event_extraction(
        self,
        source_id: str,
        model_id: str,
        prompt_version: str,
        *,
        expected_epoch: str,
    ) -> bool:
        with self._lock:
            state = self.initialize()
            if state.execution_epoch != expected_epoch or not state.is_reconciled:
                raise RuntimeError("worker lost execution epoch ownership")
            key = (source_id, model_id, prompt_version)
            if key in self._event_extractions:
                return False
            self._event_extractions.add(key)
            return True

    def release_event_extraction(
        self,
        source_id: str,
        model_id: str,
        prompt_version: str,
        *,
        expected_epoch: str,
    ) -> None:
        with self._lock:
            state = self.initialize()
            if state.execution_epoch != expected_epoch or not state.is_reconciled:
                raise RuntimeError("worker lost execution epoch ownership")
            self._event_extractions.discard((source_id, model_id, prompt_version))

    def claim_order(
        self, execution: OrderExecution, *, expected_epoch: str, max_active_orders: int
    ) -> bool:
        with self._lock:
            state = self.initialize()
            client_order_id = execution.plan.client_order_id
            if (
                state.mode is not AgentMode.RUNNING
                or state.execution_epoch != expected_epoch
                or not state.is_reconciled
            ):
                raise RuntimeError("agent is not authorized for new exposure")
            existing = self._orders.get(client_order_id)
            if existing is not None:
                if (
                    existing.status in {OrderExecutionStatus.PREPARED, OrderExecutionStatus.UNKNOWN}
                    and client_order_id not in state.active_order_ids
                ):
                    raise RuntimeError("agent is not authorized for order recovery")
                return False
            if len(state.active_order_ids) >= max_active_orders:
                raise RuntimeError("agent is not authorized for new exposure")
            self._state = state.model_copy(
                update={
                    "active_order_ids": (*state.active_order_ids, client_order_id),
                    "version": state.version + 1,
                    "updated_at": datetime.now(UTC),
                }
            )
            self._orders[client_order_id] = execution
            return True

    def get_order(self, client_order_id: str) -> OrderExecution | None:
        with self._lock:
            return self._orders.get(client_order_id)

    def clear_active_order(self, client_order_id: str) -> AgentState:
        with self._lock:
            state = self.initialize()
            if client_order_id not in state.active_order_ids:
                raise RuntimeError("active order changed concurrently")
            self._state = state.model_copy(
                update={
                    "active_order_ids": tuple(
                        tracked for tracked in state.active_order_ids if tracked != client_order_id
                    ),
                    "version": state.version + 1,
                    "updated_at": datetime.now(UTC),
                }
            )
            return self._state

    def update_equity_peak(self, equity: Decimal) -> AgentState:
        with self._lock:
            state = self.initialize()
            if state.equity_peak is not None and equity <= state.equity_peak:
                return state
            self._state = state.model_copy(
                update={
                    "equity_peak": equity,
                    "version": state.version + 1,
                    "updated_at": datetime.now(UTC),
                }
            )
            return self._state

    def update_order(
        self,
        execution: OrderExecution,
        *,
        expected_status: OrderExecutionStatus,
    ) -> OrderExecution:
        with self._lock:
            client_order_id = execution.plan.client_order_id
            current = self._orders.get(client_order_id)
            if current is None:
                raise RuntimeError("order execution does not exist")
            if current.status is not expected_status or execution.version != current.version + 1:
                raise RuntimeError("order execution changed concurrently")
            self._orders[client_order_id] = execution
            return execution

    def list_public_decisions(self, limit: int = 50) -> list[PublicDecisionRecord]:
        with self._lock:
            now = datetime.now(UTC)
            records = [
                record
                for record in self._decisions.values()
                if record.public and record.occurred_at + self._public_delay <= now
            ]
            selected = sorted(records, key=lambda record: record.occurred_at, reverse=True)[:limit]
            return [record.public_projection() for record in selected]

    def list_public_routes(self, limit: int = 100) -> list[PublicDecisionRecord]:
        with self._lock:
            now = datetime.now(UTC)
            records = sorted(
                (
                    record
                    for record in self._decisions.values()
                    if record.public
                    and record.route is not None
                    and record.occurred_at + self._public_delay <= now
                ),
                key=lambda record: record.occurred_at,
                reverse=True,
            )[:limit]
            return [record.public_projection() for record in records]

    def list_public_portfolio(self, limit: int = 200) -> list[PublicPortfolioPoint]:
        with self._lock:
            now = datetime.now(UTC)
            points = sorted(
                (
                    point
                    for point in self._public_portfolio.values()
                    if point.captured_at + self._public_delay <= now
                ),
                key=lambda point: point.captured_at,
            )
            return points[-limit:]

    def list_public_decision_page(
        self,
        *,
        limit: int = 25,
        cursor: str | None = None,
        search: str | None = None,
        route: Route | None = None,
        decision_type: str | None = None,
    ) -> PublicDecisionPage:
        try:
            offset = int(cursor) if cursor is not None else 0
        except ValueError as error:
            raise ValueError("invalid cursor") from error
        if offset < 0:
            raise ValueError("invalid cursor")

        normalized_search = search.casefold().strip() if search else None
        normalized_type = decision_type.casefold() if decision_type else None
        with self._lock:
            now = datetime.now(UTC)
            records = sorted(
                (
                    record.public_projection()
                    for record in self._decisions.values()
                    if record.public and record.occurred_at + self._public_delay <= now
                ),
                key=lambda record: record.occurred_at,
                reverse=True,
            )
        filtered = [
            record
            for record in records
            if (route is None or record.route is route)
            and (normalized_type is None or record.decision_type.casefold() == normalized_type)
            and (
                normalized_search is None
                or normalized_search
                in " ".join(
                    value
                    for value in (
                        record.symbol,
                        record.decision_type,
                        record.route,
                        record.summary,
                    )
                    if value
                ).casefold()
            )
        ]
        page = filtered[offset : offset + limit]
        next_offset = offset + len(page)
        return PublicDecisionPage(
            records=page,
            next_cursor=str(next_offset) if next_offset < len(filtered) else None,
        )

